/* ===== Sacramentos y Agenda ===== */
const TIPOS=['Bautismo','Primera comunión','Confirmación','Matrimonio','Defunción'];
const libOf=a=>rec('libros',a.libro)||{num:'?'};
const actaRef=a=>`${libOf(a).num}·${a.folio}·${a.num}`;
const ministros=()=>DB.clero.filter(c=>c.estado=='Activo').map(c=>c.nombre);
const libLab=l=>`${l.tipo} · libro ${l.num}${l.estado=='Cerrado'?' (cerrado)':''}`;
function nuevaActa(tipo,pid){const p=pid&&rec('personas',pid);const lb=DB.libros.find(l=>l.tipo==tipo&&l.estado=='Abierto');
 const pre={tipo,fecha:HOY,lugar:'Parroquia San José',ministro:'Pbro. Luis Alberto Torres',libro:'',folio:'',num:''};
 if(p)Object.assign(pre,{personaId:pid,persona:p.nombres+' '+p.apellidos,nac:p.nac});if(tipo=='Matrimonio'&&p)pre.conyuge1=p.nombres+' '+p.apellidos;
 FS=null;abrirForm('actas',null,pre)}
E.actas={s:'acta',p:'Actas',art:'la',mod:'Sacramentos',nuevo:'Registrar sacramento',del:'anular',anulado:'Anulada',motivoEdit:1,editT:'Rectificar acta',saveL:'Inscribir en el libro',
 get steps(){const t=FS&&FS.vals.tipo;return t=='Matrimonio'?['Contrayentes','Testigos','Celebración y libro']:t=='Defunción'?['Difunto','Familia y sepultura','Exequias y libro']:['Persona','Padres y padrinos','Celebración y libro']},
 newT:v=>'Registrar '+(v.tipo||'sacramento').toLowerCase(),
 f:v=>{const t=v.tipo;const L=[{k:'tipo',l:'Sacramento',t:'sel',o:TIPOS,req:1,step:0,ro:1}];
  if(t=='Matrimonio')L.push({k:'conyuge1',l:'Contrayente 1',req:1,step:0,w:1},{k:'conyuge2',l:'Contrayente 2',req:1,step:0,w:1},{k:'expediente',l:'Expediente matrimonial',t:'ref',ref:'expedientes',lab:x=>x.novio.split(' ')[0]+' – '+x.novia.split(' ')[0]+' · '+x.fecha,step:0,w:1},{k:'testigo1',l:'Testigo 1',req:1,step:1},{k:'testigo2',l:'Testigo 2',req:1,step:1},{k:'persona',l:'Nombre del acta',hide:1,view:1});
  else{L.push({k:'persona',l:t=='Defunción'?'Nombre del difunto':'Nombre completo',req:1,step:0,w:1},{k:'personaId',l:'Vincular con ficha',t:'ref',ref:'personas',lab:p=>p.nombres+' '+p.apellidos+(p.dni?' · '+p.dni:''),step:0,w:1,help:'Opcional. Así el sacramento aparece en su ficha.'});
   if(t!='Defunción')L.push({k:'nac',l:'Fecha de nacimiento',t:'date',past:1,req:1,step:0,art:'la'},{k:'padres',l:'Padres',step:1,w:1,req:t=='Bautismo',help:'Nombres completos del padre y de la madre.'},{k:'padrino',l:'Padrino',step:1},{k:'madrina',l:'Madrina',step:1});
   else L.push({k:'causa',l:'Causa',t:'sel',o:['Natural','Enfermedad','Accidente','Otra'],step:0},{k:'declarante',l:'Familiar que declara',req:1,step:1},{k:'sepultura',l:'Lugar de sepultura',step:1})}
  L.push({k:'fecha',l:t=='Defunción'?'Fecha de exequias':'Fecha de celebración',t:'date',req:1,past:1,step:2,art:'la'},{k:'ministro',l:'Ministro',t:'sel',o:ministros,req:1,step:2},{k:'lugar',l:'Lugar',step:2},{k:'libro',l:'Libro',help:`1) <button type="button" class="btn" onclick="toast('Reporte del acta enviado a impresión (simulado). Úselo para asentar el acta en el libro físico.')">${I('print')}Imprimir reporte</button> 2) Asiente el acta en el libro físico. 3) Copie aquí libro, folio y número tal como quedaron (el sistema no los sugiere).`,t:'ref',ref:'libros',lab:libLab,fil:l=>l.tipo==t&&(l.estado=='Abierto'||l.id==v.libro),req:1,step:2},{k:'folio',l:'Folio',t:'num',req:1,step:2,help:'Escríbalo tal como quedó en el libro físico.'},{k:'num',l:'Número',t:'num',req:1,step:2,help:'Primero imprima el reporte y asiente el acta en el libro; luego copie aquí el número escrito.'},{k:'obs',l:'Observaciones',t:'area',step:2,w:1});return L},
 validate:(v,id)=>{const o={};const lb=rec('libros',v.libro);if(lb&&lb.estado=='Cerrado'&&!id)o.libro='Ese libro está cerrado. Elija el libro abierto o abra uno nuevo en «Libros».';
  const d=DB.actas.find(a=>a.id!=id&&a.libro==v.libro&&+a.folio==+v.folio&&+a.num==+v.num);if(d)o.num=`Ya existe un acta con ese libro, folio y número (${esc(d.persona)}). Revise el libro físico y corrija.`;
  if(/Bautismo|Confirmación/.test(v.tipo)&&v.padrino===''&&v.madrina==='')o.padrino='Indique al menos un padrino o una madrina.';
  if(v.nac&&v.fecha&&iso(v.nac)>iso(v.fecha))o.nac='La fecha de nacimiento no puede ser posterior a la celebración.';return o},
 confirmSave:{t:v=>'¿Inscribir el acta en el libro?',txt:v=>`Se creará el acta <b>${libOf(v).num} · folio ${v.folio} · n.º ${v.num}</b> de ${esc(v.persona||v.conyuge1+' y '+v.conyuge2)}. Quedará pendiente de la firma del párroco.`,ok:'Sí, inscribir'},
 onCreate:r=>{if(r.tipo=='Matrimonio')r.persona=r.conyuge1+' y '+r.conyuge2;r.estado='Pendiente firma';r.notas=[];const lb=rec('libros',r.libro);if(lb){lb.numero=Math.max(lb.numero,+r.num);lb.folio=Math.max(lb.folio,+r.folio)}},
 createAcc:'Inscribió el acta',savedMsg:r=>`Acta inscrita: ${actaRef(r)} · ${r.persona}`,
 onEdit:(r,mot)=>{r.notas=r.notas||[];r.notas.push({f:HOY,tipo:'Rectificación',t:mot});if(r.estado=='Inscrita')r.estado='Inscrita'},
 title:r=>r.persona||'',status:r=>r.estado,sub2:r=>esc(r.tipo)+' · '+actaRef(r),
 cols:[col('Nombre','persona',{b:1}),col('Acta','folio',{s:r=>libOf(r).num+String(r.folio).padStart(4,'0')+String(r.num).padStart(4,'0'),f:r=>`${actaRef(r)}<small>${r.tipo}</small>`,c:'hm'}),col('Fecha','fecha',{d:1,key:1,f:r=>`${r.fecha}<span class="muted"> · ${r.tipo}</span>`}),col('Ministro','ministro',{c:'hm'}),col('Estado','estado',{f:r=>sb(r.estado)}),col('','x',{ns:1,f:r=>`<button class="btn g" onclick="event.stopPropagation();partida('${r.id}')">${I('doc')}Partida</button>`})],
 chips:[['Todas',()=>1],...TIPOS.map(t=>[t,r=>r.tipo==t]),['Pendiente firma',r=>r.estado=='Pendiente firma'],['Anuladas',r=>r.estado=='Anulada']],
 ph:'Buscar por nombre, libro o ministro…',bulk:[['Enviar a firma',ids=>toast(ids.length+' actas enviadas al párroco para firma (simulado).')],['Exportar',ids=>exportar('Actas ('+ids.length+')')]],
 warn:r=>r.estado=='Anulada'?`<div class="esum">${I('ban')} Acta anulada. Motivo: ${esc(r.motivo||'—')}. No se pueden emitir partidas.</div>`:r.estado=='Pendiente firma'?`<div class="nt">${I('warn')}<span>Pendiente de la firma del párroco.</span></div>`:'',
 extra2:r=>`<h4>Vista del acta</h4><div class="paper" style="font-size:.9rem;padding:1.2rem">${actaTexto(r)}</div>`,
 tabs:r=>[['Notas marginales',()=>notasView(r)]],
 acts:r=>`${r.estado=='Pendiente firma'?`<button class="btn" onclick="firmar('${r.id}')">${I('check')}Firmar</button>`:''}${r.estado!='Anulada'?`<button class="btn" onclick="partida('${r.id}')">${I('doc')}Emitir partida</button>`:''}`,
 print:r=>preview('Acta '+actaRef(r),paperHead('ACTA DE '+r.tipo.toUpperCase(),`Libro ${libOf(r).num} · Folio ${r.folio} · Número ${r.num}`)+actaTexto(r)+seal())};
function actaTexto(r){const t=r.tipo;let s;
 if(t=='Matrimonio')s=`El ${r.fecha}, en ${esc(r.lugar)}, contrajeron matrimonio canónico <b>${esc(r.conyuge1)}</b> y <b>${esc(r.conyuge2)}</b>, ante el ${esc(r.ministro)}. Fueron testigos ${esc(r.testigo1)} y ${esc(r.testigo2)}.`;
 else if(t=='Defunción')s=`El ${r.fecha} se celebraron las exequias de <b>${esc(r.persona)}</b>, presididas por ${esc(r.ministro)}. Causa: ${esc(r.causa||'—')}. Sepultura: ${esc(r.sepultura||'—')}. Declaró: ${esc(r.declarante||'—')}.`;
 else s=`El ${r.fecha}, en ${esc(r.lugar)}, ${esc(r.ministro)} administró el sacramento de${t=='Bautismo'?'l bautismo':t=='Confirmación'?' la confirmación':' la primera comunión'} a <b>${esc(r.persona)}</b>, nacido(a) el ${esc(r.nac||'—')}${r.padres?`, hijo(a) de ${esc(r.padres)}`:''}.${r.padrino||r.madrina?` Padrinos: ${esc([r.padrino,r.madrina].filter(Boolean).join(' y '))}.`:''}`;
 return `<p>${s}</p>${(r.notas||[]).length?`<p><i>Notas marginales:</i> ${r.notas.map(n=>esc(n.f+' — '+n.t)).join(' ')}</p>`:'<p><i>Notas marginales:</i> ninguna.</p>'}`}
function notasView(r){return `${(r.notas||[]).length?`<div class="tl">${r.notas.map(n=>`<div class="ok"><b style="font-weight:600">${esc(n.tipo)}</b> <small>· ${n.f}</small><br>${esc(n.t)}</div>`).join('')}</div>`:emptyState('Sin notas marginales','Aquí se anotan matrimonios, confirmaciones, rectificaciones u otras observaciones.')}
 ${r.estado!='Anulada'?`<h4>Agregar nota marginal</h4><div class="fld"><span>Tipo de nota</span><select id="nt_t">${['Matrimonio','Confirmación','Rectificación','Nulidad','Ordenación','Profesión religiosa','Otra'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="fld"><span>Texto de la nota <span class="req">(obligatorio)</span></span><textarea id="nt_x" placeholder="Ej.: Contrajo matrimonio el 07/06/2026 en esta parroquia (Libro VIII, f. 12, n.º 58)."></textarea><div id="nt_e"></div></div><button class="btn p" onclick="addNota('${r.id}')">${I('plus')}Agregar nota</button>`:''}`}
function addNota(id){const r=rec('actas',id),t=$('#nt_x').value.trim(),tp=$('#nt_t').value;if(t.length<8){$('#nt_e').innerHTML=`<div class="fe" role="alert">${I('warn')}Escriba la nota con un poco más de detalle (mínimo 8 letras).</div>`;$('#nt_x').setAttribute('aria-invalid','true');$('#nt_x').focus();return}
 commit('Nota marginal agregada',()=>{r.notas.push({f:HOY,tipo:tp,t});hist(r,'Agregó nota marginal: '+tp)},{acc:'Agregó nota marginal',ent:'Sacramentos',obj:'Acta '+actaRef(r),despues:{Nota:t}},{keep:1});det('actas',id,1)}
function firmar(id){const r=rec('actas',id);ask({t:'Firmar acta',txt:`Firma digital del párroco para el acta ${actaRef(r)} de ${esc(r.persona)}.`,html:`<div class="fld"><span>PIN de firma (demo: cualquier número de 4 cifras)</span><input id="pin" inputmode="numeric" maxlength="4" value="${window.KEEP?'1234':''}"></div>`,ok:'Firmar',onok:()=>{if(!/^\d{4}$/.test($('#pin')?.value||'1234')){}commit('Acta firmada',()=>{r.estado='Inscrita';hist(r,'Firmó el párroco',[['Estado','Pendiente firma','Inscrita']])},{acc:'Firmó acta',ent:'Sacramentos',obj:'Acta '+actaRef(r),antes:{Estado:'Pendiente firma'},despues:{Estado:'Inscrita'}},{keep:1});det('actas',id)}})}
function vActas(){const lb=DB.libros.filter(l=>l.estado=='Abierto');return ph('Sacramentos','Libros abiertos: '+lb.map(l=>l.tipo.toLowerCase()+' '+l.num).join(' · '),`<div class="dd" id="nsac"><button class="btn p" onclick="event.stopPropagation();this.parentNode.classList.toggle('on')" aria-haspopup="true">${I('plus')}Registrar sacramento${I('chev')}</button><div class="ddm">${TIPOS.map(t=>`<button onclick="nuevaActa('${t}')">${I('book')}${t}</button>`).join('')}</div></div>`)+table('actas',{ent:'actas',rows:()=>DB.actas,cols:E.actas.cols,chips:E.actas.chips,ph:E.actas.ph,bulk:E.actas.bulk,empty:['Todavía no hay actas','Registre el primer sacramento con el botón de arriba.']})}

/* partida */
let PT={};
function partida(id,step){const a=rec('actas',id);cerrar();
 if(a.estado=='Anulada'){ask({t:'No se puede emitir',txt:`El acta ${actaRef(a)} está anulada (${esc(a.motivo||'')}). Si hay un acta correcta, emita la partida desde ella.`,ok:'Entendido',undo:false,onok:()=>{}});return}
 if(!step){PT={id,motivo:'',sol:a.persona,medio:'Efectivo',err:{},exo:''}}
 const ar=DB.aranceles.find(x=>x.concepto.includes('Partida de '+(a.tipo=='Matrimonio'?'matrimonio':a.tipo=='Confirmación'?'confirmación':'bautismo')))||{monto:25};const e=PT.err;
 const fe=k=>e[k]?`<div class="fe" role="alert">${I('warn')}${e[k]}</div>`:'';
 $('#md').style.width='44rem';$('#md').innerHTML=`<div class="drh"><div><h2>Emitir partida de ${a.tipo.toLowerCase()}</h2><p>${esc(a.persona)} · ${actaRef(a)}</p></div><button class="btn g" onclick="cerrar()">${I('x')}Cerrar</button></div>
 <form class="drb" onsubmit="event.preventDefault();partidaOk()" id="ptf">${Object.keys(e).length?`<div class="esum" role="alert">Revise los datos marcados.</div>`:''}<div class="fg">
 <div class="fld"><span>Motivo de la solicitud <span class="req">(obligatorio)</span></span><select id="pt_m" ${e.m?'aria-invalid="true"':''}><option value="">Elija…</option>${['Matrimonio','Confirmación','Primera comunión','Padrino o madrina','Trámite personal','Colegio','Otro'].map(x=>`<option ${PT.motivo==x?'selected':''}>${x}</option>`).join('')}</select>${fe('m')}</div>
 <div class="fld"><span>Solicitante <span class="req">(obligatorio)</span></span><input id="pt_s" value="${esc(PT.sol)}" ${e.s?'aria-invalid="true"':''}>${fe('s')}</div>
 <div class="fld"><span>Medio de pago</span><select id="pt_p" onchange="PT.medio=this.value;PT.motivo=$('#pt_m').value;PT.sol=$('#pt_s').value;partida('${id}',1)">${['Efectivo','Yape','Transferencia','Exonerado'].map(x=>`<option ${PT.medio==x?'selected':''}>${x}</option>`).join('')}</select>${fe('p')}</div>
 <div class="fld"><span>Arancel</span><input value="${PT.medio=='Exonerado'?'S/ 0,00':money(ar.monto)}" readonly><div class="fh">Según la tabla de aranceles vigente.</div></div>
 ${PT.medio=='Exonerado'?`<div class="fld w2"><span>Motivo de la exoneración <span class="req">(obligatorio)</span></span><input id="pt_x" value="${esc(PT.exo)}" ${e.x?'aria-invalid="true"':''}>${fe('x')}</div>`:''}</div>
 <div class="info">${I('help')}<span>Al cobrar se genera el recibo y el ingreso en Finanzas automáticamente.</span></div></form>
 <div class="drf"><button class="btn" onclick="cerrar()">Cancelar</button><button class="btn p" onclick="partidaOk()">${I('coin')}${PT.medio=='Exonerado'?'Generar partida':'Cobrar '+money(ar.monto)+' y generar'}</button></div>`;PT.monto=PT.medio=='Exonerado'?0:ar.monto;scr(true);$('#md').classList.add('on')}
function partidaOk(){const a=rec('actas',PT.id);PT.motivo=$('#pt_m').value;PT.sol=$('#pt_s').value.trim();PT.exo=$('#pt_x')?.value.trim()||'';PT.err={};
 if(!PT.motivo)PT.err.m='Elija para qué necesita la partida.';if(!PT.sol)PT.err.s='Escriba el nombre de quien la solicita.';if(PT.medio=='Exonerado'&&PT.exo.length<4)PT.err.x='Indique por qué se exonera el pago.';if(PT.medio=='Efectivo'&&!DB.caja.abierta)PT.err.p='La caja está cerrada. Ábrala en Finanzas › Caja diaria o elija otro medio de pago.';
 if(Object.keys(PT.err).length)return partida(PT.id,1);
 const rnum='R-'+(2043+DB.movimientos.filter(m=>m.recibo?.startsWith('R-')).length);
 commit('Partida emitida y cobrada · recibo '+rnum,()=>{if(PT.monto)DB.movimientos.unshift({id:nid('mv'),fecha:HOY,tipo:'Ingreso',concepto:`Partida de ${a.tipo.toLowerCase()} · ${a.persona}`,categoria:'Aranceles',cuenta:PT.medio=='Efectivo'?'Caja':'BCP ···4021',monto:PT.monto,medio:PT.medio,recibo:rnum,estado:'Pendiente',h:[]});hist(a,'Emitió partida · motivo: '+PT.motivo)},{acc:'Emitió partida',ent:'Sacramentos',obj:'Partida '+actaRef(a),despues:{Motivo:PT.motivo,Solicitante:PT.sol,Arancel:money(PT.monto),Recibo:PT.monto?rnum:'Exonerado'}},{keep:1});
 partidaPrev(a,rnum)}
function partidaPrev(a,rnum){const t=a.tipo;preview('Partida de '+t.toLowerCase(),paperHead('PARTIDA DE '+t.toUpperCase(),`Libro ${libOf(a).num} · Folio ${a.folio} · Número ${a.num}`)+`<p>El suscrito Párroco certifica que en el libro de ${t=='Bautismo'?'bautismos':t=='Matrimonio'?'matrimonios':t=='Defunción'?'defunciones':t.toLowerCase()+'es'} de esta parroquia consta lo siguiente:</p>${actaTexto(a)}<p>Se expide a solicitud de ${esc(PT.sol||a.persona)}, para fines de <b>${esc((PT.motivo||'trámite').toLowerCase())}</b>.</p><p>${esc(DB.cfg.nombre)}, 13 de octubre de 2026.</p><p style="margin-top:2rem">${esc(DB.cfg.parroco)}<br><small>Párroco</small></p>${seal()}<small style="font-family:var(--sans);color:var(--t3)">Código de verificación SJ-2026-${a.num}-7F3A · válida por seis meses</small>`,{sub:actaRef(a),btns:rnum&&PT.monto?`<button class="btn" onclick="reciboMov('${rnum}')">${I('doc')}Ver recibo</button>`:''})}
function reciboMov(rn){const m=DB.movimientos.find(x=>x.recibo==rn);if(!m)return toast('No se encontró el recibo.');recibo(m)}
function recibo(m){preview(`Recibo ${m.recibo}`,paperHead((m.tipo=='Egreso'?'COMPROBANTE DE EGRESO':'RECIBO DE INGRESO')+' N.º '+esc(m.recibo),'RUC '+DB.cfg.ruc)+`<table style="font-family:var(--sans);font-size:.95rem"><tbody><tr><td>Fecha</td><td>${m.fecha}</td></tr><tr><td>Concepto</td><td style="white-space:normal">${esc(m.concepto)}</td></tr><tr><td>Categoría</td><td>${esc(m.categoria)}</td></tr><tr><td>Medio de pago</td><td>${esc(m.medio)}</td></tr><tr><td><b>Importe</b></td><td><b>${money(m.monto)}</b></td></tr></tbody></table><p style="margin-top:2rem;font-family:var(--sans);font-size:.9rem">Recibido por: ${esc(DB.me.nombre)}</p>${m.estado=='Anulado'?'<p style="color:var(--ac);font:700 1.4rem var(--sans);border:2px solid var(--ac);display:inline-block;padding:.2rem .6rem;transform:rotate(-6deg)">ANULADO</p>':''}${seal()}`,{sub:money(m.monto)})}

/* libros */
E.libros={s:'libro',p:'Libros sacramentales',art:'el',mod:'Sacramentos',nuevo:'Abrir libro nuevo',noDel:1,
 f:r=>[{k:'tipo',l:'Sacramento',t:'sel',o:TIPOS,req:1},{k:'num',l:'Número del libro (romano)',req:1,help:'Ejemplo: XIII'},{k:'apertura',l:'Fecha de apertura',t:'date',req:1},{k:'folios',l:'Cantidad de folios',t:'num',req:1,min:10},{k:'estado',l:'Estado',view:1}],
 defaults:()=>({apertura:HOY,folios:200}),
 validate:(v,id)=>{const o={};const ab=DB.libros.find(l=>l.tipo==v.tipo&&l.estado=='Abierto'&&l.id!=id);if(ab&&!id)o.tipo=`Ya hay un libro de ${v.tipo.toLowerCase()} abierto (${ab.num}). Ciérrelo antes de abrir otro.`;if(v.num&&!/^[IVXLC]+$/i.test(v.num))o.num='Use números romanos, por ejemplo XIII.';return o},
 onCreate:r=>{r.estado='Abierto';r.folio=1;r.numero=Math.max(0,...DB.libros.filter(l=>l.tipo==r.tipo).map(l=>l.numero));r.cierre='';r.num=r.num.toUpperCase()},
 title:r=>`${r.tipo} · libro ${r.num}`,status:r=>r.estado,sub2:r=>'Abierto el '+r.apertura,
 cols:[col('Libro','num',{f:r=>esc(r.tipo)+' · '+r.num}),col('Apertura','apertura',{d:1,c:'hm'}),col('Uso','folio',{key:1,s:r=>r.folio/r.folios,f:r=>`<span class="bar"><i style="width:${Math.round(r.folio/r.folios*100)}%"></i></span>folio ${r.folio} de ${r.folios}`}),col('Último n.º','numero',{c:'num hm'}),col('Estado','estado',{f:r=>sb(r.estado)})],
 chips:[['Todos',()=>1],['Abiertos',r=>r.estado=='Abierto'],['Cerrados',r=>r.estado=='Cerrado']],
 extra2:r=>`<h4>Registro</h4><div class="kv"><span>Último folio registrado</span><b>${r.folio}</b></div><div class="kv"><span>Último número registrado</span><b>${r.numero}</b></div><p class="sm muted">Dato informativo: folio y número se copian a mano del libro físico en cada acta.</p>${r.folios-r.folio<20&&r.estado=='Abierto'?`<div class="nt">${I('warn')}Quedan pocos folios. Prepare la apertura de un libro nuevo.</div>`:''}<h4>Últimas actas</h4>${DB.actas.filter(a=>a.libro==r.id).slice(0,5).map(a=>`<div class="kv"><a href="#" onclick="event.preventDefault();det('actas','${a.id}')">${esc(a.persona)}</a><span>${a.folio}·${a.num}</span></div>`).join('')||'<p class="muted sm">Sin actas.</p>'}`,
 acts:r=>r.estado=='Abierto'?`<button class="btn" onclick="cerrarLibro('${r.id}')">${I('lock')}Cerrar libro</button>`:''};
function cerrarLibro(id){const l=rec('libros',id);ask({t:`¿Cerrar el libro ${l.num} de ${l.tipo.toLowerCase()}?`,txt:'Ya no se podrán inscribir actas en él. Se imprimirá el acta de cierre para la firma del párroco.',typed:'CERRAR',ok:'Cerrar libro',danger:1,onok:()=>{commit(`Libro ${l.num} cerrado`,()=>{l.estado='Cerrado';l.cierre=HOY;hist(l,'Cerró el libro',[['Estado','Abierto','Cerrado']])},{acc:'Cerró libro',ent:'Sacramentos',obj:l.tipo+' '+l.num},{keep:1});det('libros',id)}})}

