const expProg=x=>Object.values(x.req).filter(r=>r[0]).length+'/'+Object.keys(x.req).length;
E.expedientes={s:'expediente',p:'Expedientes matrimoniales',art:'el',mod:'Sacramentos',nuevo:'Nuevo expediente',del:'anular',anulado:'Anulado',
 f:r=>[{k:'novio',l:'Novio',req:1,w:1},{k:'novia',l:'Novia',req:1,w:1},{k:'fecha',l:'Fecha prevista de la boda',t:'date',req:1,future:1,art:'la'},{k:'hora',l:'Hora',t:'time'},{k:'parroquia',l:'Parroquia de la boda',t:'sel',o:()=>DB.parroquias.map(p=>p.nombre)},{k:'tel',l:'Celular de contacto',t:'tel',req:1},{k:'estado',l:'Estado',t:'sel',o:['En preparación','En trámite','Completo'],req:1}],
 defaults:()=>({estado:'En preparación',parroquia:'San José',req:Object.fromEntries(['Fe de bautismo del novio','Fe de bautismo de la novia','Copia de DNI de ambos','Certificado de curso prematrimonial','Constancia de soltería','Partida de confirmación'].map(k=>[k,['','']])),proclamas:[['','Pendiente'],['','Pendiente'],['','Pendiente']],entrevista:{fecha:'',por:'',notas:'',hecha:0},dispensas:[]}),
 validate:v=>{const o={};if(v.fecha&&daysBetween(HOY,v.fecha)<30)o.fecha='El expediente debe abrirse al menos 30 días antes de la boda (faltan '+daysBetween(HOY,v.fecha)+').';return o},
 title:r=>r.novio.split(' ').slice(0,2).join(' ')+' y '+r.novia.split(' ').slice(0,2).join(' '),status:r=>r.estado,sub2:r=>'Boda: '+r.fecha+(r.hora?' · '+r.hora:''),
 cols:[col('Contrayentes','novio',{f:r=>esc(E.expedientes.title(r))}),col('Boda','fecha',{d:1,key:1}),col('Documentos','req',{s:r=>Object.values(r.req).filter(x=>x[0]).length,f:r=>{const a=Object.values(r.req).filter(x=>x[0]).length,b=Object.keys(r.req).length;return `<span class="bar"><i style="width:${a/b*100}%"></i></span>${a}/${b}`},c:'hm'}),col('Estado','estado',{f:r=>sb(r.estado)})],
 chips:[['Todos',()=>1],['En trámite',r=>r.estado=='En trámite'],['Completos',r=>r.estado=='Completo'],['Con documentos faltantes',r=>Object.values(r.req).some(x=>!x[0])]],
 tabs:r=>[['Requisitos',()=>`<p class="sm muted">Marque cada documento al recibirlo y adjunte la copia escaneada.</p>${Object.entries(r.req).map(([k,v],i)=>`<div class="kv" style="align-items:center;gap:.6rem;flex-wrap:wrap"><label style="display:flex;gap:.6rem;align-items:center;min-height:2.6rem;flex:1"><input type="checkbox" ${v[0]?'checked':''} onchange="expReq('${r.id}',${i},this.checked)">${esc(k)}</label>${v[1]?`<span class="tag">${I('clip')} ${esc(v[1])}</span>`:''}<button class="btn g" onclick="expAdj('${r.id}',${i})">${I('clip')}${v[1]?'Reemplazar':'Adjuntar'}</button></div>`).join('')}`],
  ['Proclamas',()=>`<p class="sm muted">Las proclamas se publican tres domingos seguidos antes de la boda.</p>${r.proclamas.map((p,i)=>`<div class="fg" style="align-items:end"><div class="fld"><span>${i+1}.ª proclama</span><input id="pr_${i}" value="${esc(p[0])}" placeholder="dd/mm/aaaa"></div><div class="fld"><span>Estado</span><select id="ps_${i}">${['Pendiente','Publicada','Dispensada'].map(x=>`<option ${x==p[1]?'selected':''}>${x}</option>`).join('')}</select></div></div>`).join('')}<div id="pr_e"></div><button class="btn p" onclick="expProc('${r.id}')">Guardar proclamas</button>`],
  ['Entrevista',()=>{const e=r.entrevista;return `<div class="fg"><div class="fld"><span>Fecha</span><input id="en_f" value="${esc(e.fecha)}" placeholder="dd/mm/aaaa"></div><div class="fld"><span>Entrevistador</span><select id="en_p"><option value="">Elija…</option>${ministros().map(m=>`<option ${m==e.por?'selected':''}>${m}</option>`).join('')}</select></div><div class="fld w2"><span>Notas (reservadas)</span><textarea id="en_n">${esc(e.notas)}</textarea></div></div><label style="display:flex;gap:.5rem;align-items:center;min-height:2.6rem"><input type="checkbox" id="en_h" ${e.hecha?'checked':''}>La entrevista ya se realizó y no hay impedimentos</label><div id="en_e"></div><button class="btn p" onclick="expEnt('${r.id}')">Guardar entrevista</button>`}],
  ['Dispensas',()=>`${r.dispensas.length?r.dispensas.map((d,i)=>`<div class="kv" style="align-items:center"><span>${esc(d[0])}</span><span class="row">${sb(d[1])}${d[1]!='Concedida'?`<button class="btn g" onclick="expDisp('${r.id}',${i})">${I('check')}Marcar concedida</button>`:''}</span></div>`).join(''):emptyState('Sin dispensas','Solo se necesitan en casos especiales (matrimonio mixto, disparidad de culto, etc.).')}<h4>Solicitar dispensa</h4><div class="row"><select class="sel grow" id="ds_t" aria-label="Tipo de dispensa">${['Matrimonio mixto','Disparidad de culto','Proclamas','Edad','Consanguinidad'].map(x=>`<option>${x}</option>`).join('')}</select><button class="btn" onclick="expDispAdd('${r.id}')">${I('plus')}Solicitar</button></div>`]],
 acts:r=>`${r.estado!='Completo'&&r.estado!='Anulado'?`<button class="btn" onclick="expAprobar('${r.id}')">${I('check')}Aprobar expediente</button>`:''}${r.estado=='Completo'?`<button class="btn" onclick="nuevaActa('Matrimonio');Object.assign(FS.vals,{conyuge1:'${esc(r.novio)}',conyuge2:'${esc(r.novia)}',expediente:'${r.id}'});abrirForm('actas')">${I('book')}Registrar matrimonio</button>`:''}`};
function expSave(id,msg,fn,tab){const r=rec('expedientes',id);commit(msg,()=>{fn(r);hist(r,msg)},{acc:msg,ent:'Sacramentos',obj:'Expediente '+E.expedientes.title(r)},{keep:1});det('expedientes',id,tab)}
function expReq(id,i,v){expSave(id,v?'Marcó un documento como entregado':'Desmarcó un documento',r=>{Object.values(r.req)[i][0]=v?'ok':''},1)}
function expAdj(id,i){const k=Object.keys(rec('expedientes',id).req)[i];expSave(id,'Adjuntó «'+k+'»',r=>{const v=Object.values(r.req)[i];v[1]=norm(k).replace(/[^a-z]+/g,'_').slice(0,24)+'.pdf';v[0]='ok'},1)}
function expProc(id){const vals=[0,1,2].map(i=>[$('#pr_'+i).value.trim(),$('#ps_'+i).value]);const bad=vals.find(v=>v[0]&&!/^\d\d\/\d\d\/\d{4}$/.test(v[0]));if(bad){$('#pr_e').innerHTML=`<div class="fe" role="alert">${I('warn')}Escriba las fechas como día/mes/año. Ejemplo: 01/11/2026.</div>`;return}expSave(id,'Actualizó proclamas',r=>r.proclamas=vals,2)}
function expEnt(id){const f=$('#en_f').value.trim();if(f&&!/^\d\d\/\d\d\/\d{4}$/.test(f)){$('#en_e').innerHTML=`<div class="fe" role="alert">${I('warn')}Escriba la fecha como día/mes/año.</div>`;return}if($('#en_h').checked&&!$('#en_p').value){$('#en_e').innerHTML=`<div class="fe" role="alert">${I('warn')}Indique quién hizo la entrevista.</div>`;return}expSave(id,'Guardó la entrevista',r=>r.entrevista={fecha:f,por:$('#en_p').value,notas:$('#en_n').value,hecha:$('#en_h').checked?1:0},3)}
function expDisp(id,i){expSave(id,'Dispensa concedida',r=>r.dispensas[i][1]='Concedida',4)}
function expDispAdd(id){expSave(id,'Solicitó dispensa',r=>r.dispensas.push([$('#ds_t').value,'Solicitada']),4)}
function expAprobar(id){const r=rec('expedientes',id);const falt=Object.entries(r.req).filter(x=>!x[1][0]).map(x=>x[0]);if(!r.entrevista.hecha)falt.push('Entrevista con el párroco');r.dispensas.filter(d=>d[1]!='Concedida').forEach(d=>falt.push('Dispensa: '+d[0]));
 if(falt.length){ask({t:'Todavía no se puede aprobar',txt:'Falta completar:',html:`<ul>${falt.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`,ok:'Entendido',undo:false,onok:()=>{}});return}
 ask({t:'¿Aprobar el expediente?',txt:'Quedará listo para registrar el matrimonio.',ok:'Aprobar',onok:()=>expSave(id,'Aprobó el expediente',r=>r.estado='Completo',0)})}

