 <div class="fld"><span>Canal</span><div class="seg" role="radiogroup">${['WhatsApp','Correo'].map(c=>`<button role="radio" aria-checked="${AV.canal==c}" class="${AV.canal==c?'on':''}" onclick="${rd()}AV.canal='${c}';render()">${I(c=='Correo'?'mail':'chat')} ${c}</button>`).join('')}</div></div>
